# -*- coding: utf-8 -*-
# Part 2: results. Every number is read from results/*.json or computed from model.py.
import model as mm

_P0 = mm.make(1)


def _row_state(u):
    """State and readouts at age 75 for a constant dose u (nominal parameters)."""
    y = mm.simulate(_P0, u)[0]
    G, sg = mm.algebra(y[0], y[1], y[2], u, _P0)
    S = float(np.ravel(mm.sim_index(y, u, _P0))[0])
    S0 = np.array(NOM["untreated"]["SIM"]); ag = np.array(NOM["ages"])
    return dict(I=y[0], M=y[1], F=y[2], G=float(np.ravel(G)[0]), SIM=S, aI=float(mm.metabolic_age(y[0])), aS=float(np.interp(S, S0, ag)))


