add(("p", r"The local identifiability analysis asks which parameters could be recovered from hypothetical cohort-mean observations, with the nominal parameters as the true values. Six observation sets were examined (Table 8): glucose, muscle and storage in an untreated cohort at five ages; the same with one treated cohort at $u = 0.4$, at 5%% and at 20%% noise; the same with a direct readout of $I$; and dose-ranging designs with two treated cohorts ($u = 0.4$ and 1.5). The information gain of the parameters that govern the optimum is small. With glucose, muscle and storage in untreated and single-dose cohorts at 5%% noise, the gain for $r_m$ is %.2f, for $\varphi$ %.2f and for $r_g$ %.2f, and %d of 16 parameter directions are constrained beyond the prior. Adding a direct readout of $I$ with a known calibration raises the gain for $r_g$ to %.2f but not for $r_m$ (%.2f). A dose-ranging design with the readout of $I$ gives gains of %.2f for $r_m$, %.2f for $\varphi$, %.2f for $n_H$ and %.2f for $r_g$, and the gain for the ratio $r_m/r_g$ that governs the optimum is %.2f, that is, its posterior standard deviation is %s of its prior value. The reason is that the muscle channel contributes little to the information-loss rate in an untreated or lightly treated cohort, so that $r_m$ is constrained only by cohorts that lose a large fraction of muscle. Cohorts at a single dose therefore cannot constrain the coupling on which the optimum depends, two doses with a direct readout constrain it only weakly, and the information-loss readout is itself assumed here to have a known calibration, which is optimistic." % (
    _c(_sc[1], "rm"), _c(_sc[1], "phi"), _c(_sc[1], "rg"), _id[_sc[1]]["n_directions_above_prior"], _c(_sc[3], "rg"), _c(_sc[3], "rm"),
    _c(_sc[4], "rm"), _c(_sc[4], "phi"), _c(_sc[4], "nH"), _c(_sc[4], "rg"), _id[_sc[4]]["ratio_gain"], pct(1 - _id[_sc[4]]["ratio_gain"], 0))))
_short = ["G, M, F; untreated cohort; 5% noise", "G, M, F; + one dose; 5% noise", "G, M, F; + one dose; 20% noise", "G, M, F, I; + one dose; 5% noise", "G, M, F, I; dose-ranging; 5% noise", "G, M, F; dose-ranging; 5% noise"]
add(("table", r"Table 8. Information gain, $1 - \mathrm{SD}_{post}/\mathrm{SD}_{prior}$, of selected parameters under six observation sets, and the gain for the ratio $r_m/r_g$. Gains below 0.1 mean that the observations barely constrain the parameter beyond its prior.",
     ["Observations", "Directions", "$r_g$", "$r_m$", r"$\varphi$", "$n_H$", "$a_u$", "$r_m/r_g$"],
     [[_short[i]] + ["%d" % _id[k]["n_directions_above_prior"]] + ["%.2f" % _c(k, p) for p in ("rg", "rm", "phi", "nH", "au")] + ["%.2f" % _id[k]["ratio_gain"]] for i, k in enumerate(_sc)],
     [3.0, 0.9, 0.7, 0.7, 0.7, 0.7, 0.7, 1.0]))
add(("fig", "Fig10_identifiability.png", r"Fig. 10. Information gain of each parameter under the six observation sets of Table 8 (rows). The cell values are $1 - \mathrm{SD}_{post}/\mathrm{SD}_{prior}$ for log-parameters with a prior standard deviation of 0.40.", 6.5))
